import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/grundlagen/einfuehrung-katalog-beispiel.png",l="/bilder/grundlagen/einfuehrung-katalog-beispiel-dropdown.png",m=JSON.parse('{"title":"Kataloge vorbereiten und Einträge verwenden","description":"","frontmatter":{"title":"Kataloge vorbereiten und Einträge verwenden","source_pageid":1268,"source_revision":5065},"headers":[],"relativePath":"einstieg/grundlagen/vom-katalog-zum-eintrag-einfuehrung.md","filePath":"einstieg/grundlagen/vom-katalog-zum-eintrag-einfuehrung.md"}'),g={name:"einstieg/grundlagen/vom-katalog-zum-eintrag-einfuehrung.md"};function s(o,e,d,u,h,p){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="kataloge-vorbereiten-und-eintrage-verwenden" tabindex="-1">Kataloge vorbereiten und Einträge verwenden <a class="header-anchor" href="#kataloge-vorbereiten-und-eintrage-verwenden" aria-label="Permalink to &quot;Kataloge vorbereiten und Einträge verwenden&quot;">​</a></h1><p>Viele Auswahllisten greifen auf schulbezogene Kataloge zurück. Bereiten Sie die benötigten Werte dort vor, bevor Sie sie bei Personen, Unterricht oder Zeugnissen zuordnen.</p><p><a href="/bilder/grundlagen/einfuehrung-katalog-beispiel.png"><img src="'+a+'" alt="Kataloge steuern, welche Daten bei der Arbeit in SchILD-NRW zur Verfügung stehen. Hier wird zum Beispiel eingestellt, welche Fahrschülerarten bei einem Schüler ausgewählt werden können." loading="lazy"></a></p><p><em>Kataloge steuern, welche Daten bei der Arbeit in SchILD-NRW zur Verfügung stehen. Hier wird zum Beispiel eingestellt, welche Fahrschülerarten bei einem Schüler ausgewählt werden können.</em></p><p>In SchILD-NRW werden viele Dropdown-Menüs benutzt oder Felder mit Daten befüllt, die für jede Schule angepasst werden sollen.</p><p>Hinter vielen dieser Dropdown-Menüs verbirgt sich ein <strong>&quot;Katalog&quot;</strong> über den eingestellt wird, welche Einträge in welcher Reihenfolge zur Verfügung stehen.</p><p>Als Katalog werden in SchILD-NRW Daten vorbereitet, bei denen dies zu erwarten ist, zum Beispiel</p><ul><li>Die anwählbaren <strong>Konfessionen</strong> mit ihren Zeugnisbezeichnungen</li><li>Welche <strong>Fahrschülerarten</strong> vorliegen, hier kann zum Beispiel auch nach Buslinien unterschieden werden</li><li>Aus welchen <strong>Orten</strong> oder <strong>Ortsteilen</strong> kommen Ihre Schüler?</li><li>Es können <strong>(DSGVO-)Einwilligungen</strong> oder <strong>Lernplattformen</strong> angelegt werden, die sich dann für jeden Schüler gesondert markieren lassen.</li></ul><p><a href="/bilder/grundlagen/einfuehrung-katalog-beispiel-dropdown.png"><img src="'+l+'" alt="Die anschließende Verwendung des Katalogs in einem Dropdown-Menü. Die Fahrschülerart kann nun in den Individualdaten gesetzt werden." loading="lazy"></a></p><p><em>Die anschließende Verwendung des Katalogs in einem Dropdown-Menü. Die Fahrschülerart kann nun in den Individualdaten gesetzt werden.</em></p><p>Aber auch anderes wird über Kataloge vorbereitet, zum Beispiel</p><ul><li><strong>Kurse</strong>, die Schülern gegeben werden können, werden zuerst als Katalog angelegt</li><li>Im Katalog <strong>Unterrichtsfächer</strong> legen Sie neben dem Fachnamen weitere Merkmale fest. Dazu gehört zum Beispiel, ob das Fach bilingual unterrichtet wird, zu einer Zwischenprüfung oder zur Sekundarstufe II gehört und auf dem Zeugnis erscheint.</li></ul><p>In Bezug auf Zeugnisse können zum Beispiel</p><ul><li>vorgefertigte <strong>Floskeln</strong> aller Art oder</li><li><strong>Ankreuzskompetenzen</strong> für Ankreuzzeugnisse</li></ul><p>über einen Katalog vorbereitet werden.</p><p>Bei vielen Arbeitsprozessen in SchILD-NRW gilt somit: Zuerst wird im Katalog vorbereitet, dann sind die Daten konkret bei Schülern oder Lehrkräften zu verwenden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vom_Katalog_zum_Eintrag_(Einf%C3%BChrung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5065.</p>',18)])])}const w=n(g,[["render",s]]);export{m as __pageData,w as default};
